using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioComponentPickRadiusValidation {
 static int checks;static void Check(bool v,string m){if(!v)throw new Exception(m);checks++;}
 public static void Run(){try{var flags=BindingFlags.Instance|BindingFlags.NonPublic;var doc=ScriptableObject.CreateInstance<StudioModelDocument>();var mesh=new Mesh();mesh.vertices=new[]{new Vector3(-1,-1,0),new Vector3(1,-1,0),new Vector3(0,1,0)};mesh.triangles=new[]{0,1,2};mesh.RecalculateNormals();mesh.RecalculateBounds();doc.nodes.Add(new StudioModelDocument.Node{name="Pick triangle",mesh=mesh,cutPolygons=new[]{0,3,0,1,2},cutTriangles=mesh.triangles});using(var editor=new StudioModelEditor(()=>{})){editor.Load(doc);editor.SelectObject(0);typeof(StudioModelEditor).GetField("xray",flags).SetValue(editor,true);var view=ScriptableObject.CreateInstance<MashBoxStudioViewport>();var rt=new RenderTexture(512,512,24);rt.Create();var camera=view.camera;camera.targetTexture=rt;camera.pixelRect=new Rect(0,0,512,512);camera.aspect=1;camera.transform.position=new Vector3(0,0,-5);camera.transform.rotation=Quaternion.identity;camera.orthographic=true;camera.orthographicSize=2;var pick=typeof(StudioModelEditor).GetMethods(flags).Single(m=>m.Name=="FindComponentAt"&&m.GetParameters().Length==6);Vector2 Point(Vector3 world){var p=camera.WorldToScreenPoint(world);return new Vector2(p.x,camera.pixelHeight-p.y)/EditorGUIUtility.pixelsPerPoint;}int Pick(Vector2 p){var ray=StudioModelEditor.PaintPointerRay(camera,p);return (int)pick.Invoke(editor,new object[]{view,p,mesh.vertices,null,null,(Ray?)ray});}foreach(bool ortho in new[]{true,false}){camera.orthographic=ortho;typeof(StudioModelEditor).GetField("mode",flags).SetValue(editor,StudioModelEditor.ComponentMode.Vertex);var vertex=Point(mesh.vertices[0]);Check(Pick(vertex+Vector2.left*17)==0,"Vertex must accept new 17-point margin");Check(Pick(vertex+Vector2.left*19)==-1,"Vertex must reject beyond 18 points");typeof(StudioModelEditor).GetField("mode",flags).SetValue(editor,StudioModelEditor.ComponentMode.Edge);var edge=Point((mesh.vertices[0]+mesh.vertices[1])*.5f);Check(Pick(edge+Vector2.up*17)>=0,"Edge must accept new 17-point margin");Check(Pick(edge+Vector2.up*19)==-1,"Edge must reject beyond 18 points");typeof(StudioModelEditor).GetField("mode",flags).SetValue(editor,StudioModelEditor.ComponentMode.Face);Check(Pick(Point(Vector3.zero))==0,"Face still selects inside polygon");Check(Pick(edge+Vector2.up*17)==-1,"Face does not gain padded hit area");var index=new StudioModelEditor.PaintBoundsIndex(new[]{new StudioModelEditor.PaintBoundsIndex.Entry{Min=vertex,Max=vertex,Component=0}});var found=new List<int>();index.Query(vertex+Vector2.left*17,found);Check(found.Contains(0),"Paint broad phase accepts increased margin");index.Query(vertex+Vector2.left*19,found);Check(found.Count==0,"Paint broad phase remains bounded");}Check(mesh.vertices.SequenceEqual(new[]{new Vector3(-1,-1,0),new Vector3(1,-1,0),new Vector3(0,1,0)}),"Picking leaves geometry unchanged");camera.targetTexture=null;Object.DestroyImmediate(rt);Object.DestroyImmediate(view);}File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../component-pick-radius-result.txt")),"PASS "+checks+" component hit-radius checks");EditorApplication.Exit(0);}catch(Exception e){File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../component-pick-radius-result.txt")),e.ToString());EditorApplication.Exit(1);}}
}
